@push('scripts')<script>document.addEventListener('DOMContentLoaded',function(){const modal=document.getElementById('driverFilterModal'),search=document.getElementById('driverModalSearch'),rows=document.getElementById('driverModalRows'),target=document.getElementById('driverFilter'),label=document.getElementById('driverFilterLabel');if(!modal)return;modal.addEventListener('shown.bs.modal',()=>{search.value='';search.focus();rows.querySelectorAll('tr').forEach(r=>r.classList.remove('d-none'))});search.addEventListener('input',()=>{const q=search.value.toLowerCase();rows.querySelectorAll('tr').forEach(r=>r.classList.toggle('d-none',!r.dataset.search.includes(q)))});rows.addEventListener('click',e=>{const b=e.target.closest('.choose-driver');if(!b)return;target.value=b.dataset.id;label.value=b.dataset.label;bootstrap.Modal.getInstance(modal)?.hide()})});</script>@endpush
@if($printMode)@push('scripts')<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),100));</script>@endpush @endif
